Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
You are given three positive integers x, y, n. Your task is to find the nearest fraction to fraction  whose denominator is no more than n. Formally, you should find such pair of integers a, b (1 ≤ b ≤ n; 0 ≤ a) that the value  is as minimal as possible.If there are multiple "nearest" fractions, choose the one with the minimum denominator. If there are multiple "nearest" fractions with the minimum denominator, choose the one with the minimum numerator.
</problem_description>

Here is the GNU C++17 code you have to repair:
<original_code>
#include <bits/stdc++.h>
#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>

using namespace std;
using namespace __gnu_pbds;

typedef long long ll;
typedef pair<ll, ll> pii;
typedef vector<ll> vi;
typedef vector<string> vs;

const ll MOD = 1000000007;
const ll INF = 1e18 + 5;
const double PI = 3.14159265358979323844;

#define pb push_back
#define ppb pop_back
#define endl '\n'
#define all(x) (x).begin(), (x).end()
#define sz(x) static_cast<ll>((x).size())
#define rep(i, a, b) for (ll i = (a); i < (b); ++i)
#define repr(i, a, b) for (ll i = (b) - 1; i >= (a); --i)
#define trace(...) 

template<typename T>
using ordered_set = tree<T, null_type, less<T>, rb_tree_tag, tree_order_statistics_node_update>;

void solve() {
    ll x, y, n;
    cin >> x >> y >> n;

    set<pii> fractions;

    rep(i, 1, n + 1) {
        ll mini = (x * i) / y;
        ll maxi = (x * i + y - 1) / y;

        if ((mini + maxi) * y > 2 * x * i) {
            ll g = __gcd(i, mini);
            fractions.insert({i / g, mini / g});
        } else {
            ll g = __gcd(i, maxi);
            fractions.insert({i / g, maxi / g});
        }
    }

    pii best = *fractions.begin();

    for (const auto& frac : fractions) {
        ll p = frac.second, q = frac.first;
        ll curr_val = p * y;
        ll target_val = x * q;

        if (curr_val == target_val) {
            best = {q, p};
        } else if (curr_val > target_val) {
            if (best.second * y > x * best.first) {
                if (p * best.first < best.second * q) {
                    best = {q, p};
                }
            } else {
                if (2 * x * best.first * q > y * (best.second * q + best.first * p)) {
                    best = {q, p};
                }
            }
        } else {
            if (best.second * y > x * best.first) {
                if (2 * x * best.first * q < y * (best.second * q + best.first * p)) {
                    best = {q, p};
                }
            } else {
                if (p * best.first > best.second * q) {
                    best = {q, p};
                }
            }
        }
    }

    ll g = __gcd(best.first, best.second);
    cout << best.second / g << '/' << best.first / g << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    ll test = 1;
    while (test--) solve();

    return 0;
}
